const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const mobile = path.resolve(__dirname, '..');
const frontend = path.resolve(mobile, '..', 'frontend');
const output = path.join(mobile, '.web-build');
const result = spawnSync(process.execPath, [path.join(frontend, 'node_modules/vite/bin/vite.js'), 'build', '--mode', 'mobile', '--outDir', output], {
  cwd: frontend, stdio: 'inherit', windowsHide: true,
});
if (result.error || result.status !== 0) throw new Error('Could not build the bundled mobile interface.');
let html = fs.readFileSync(path.join(output, 'index.html'), 'utf8');
html = html.replace(/<link[^>]+rel="icon"[^>]*>/g, '');
html = html.replace(/<link[^>]+rel="stylesheet"[^>]+href="([^"]+)"[^>]*>/g, (_match, file) => {
  const css = fs.readFileSync(path.join(output, file), 'utf8').replace(/@import\s*(?:url\()?[^;]+;/g, '');
  return '<style>' + css.replace(/<\/style/gi, '<\\/style') + '</style>';
});
let inlineScript = '';
html = html.replace(/<script[^>]+src="([^"]+)"[^>]*><\/script>/g, (_match, file) => {
  let code = fs.readFileSync(path.join(output, file), 'utf8');
  const logo = 'data:image/png;base64,' + fs.readFileSync(path.join(frontend, 'public', 'Logo.png')).toString('base64');
  code = code.replace(/"(?:\.\/|\/)Logo\.png"/g, () => JSON.stringify(logo));
  code = code.replace('new URL(`../Logo.png`,document.currentScript&&document.currentScript.tagName.toUpperCase()===`SCRIPT`&&document.currentScript.src||document.baseURI).href', () => JSON.stringify(logo));
  inlineScript += '<script>window.__mangMobile=__MANG_MOBILE_CONFIG__;</script><script>' + code.replace(/<\/script/gi, '<\\/script') + '</script>';
  return '';
});
html = html.replace('</body>', () => inlineScript + '</body>');
if (/\b(?:src|href)="(?:https?:|\.\/assets|\/assets)/.test(html) || html.includes('fonts.googleapis.com') || html.includes('Logo.png')) {
  throw new Error('The mobile interface still depends on an external asset.');
}
fs.writeFileSync(path.join(mobile, 'src', 'generated-ui.ts'), '// Generated by scripts/bundle-ui.js. Do not edit.\nexport default ' + JSON.stringify(html) + ';\n');
fs.writeFileSync(path.join(output, 'offline.html'), html.replace('__MANG_MOBILE_CONFIG__', JSON.stringify({ apiBaseUrl: 'http://127.0.0.1:4175/api', offlineShell: true })));
console.log('Bundled mobile UI ready: ' + Buffer.byteLength(html) + ' bytes, no remote scripts, styles or images.');
